            int pages = pageOffsets.get(i).size();

			pageNum += pages;

            LOG.debug("Index " + i + ": pages=" + pages);
		}

        List<Integer> offsets = pageOffsets.get(index);

        LOG.debug("Pages before this index: " + pageNum );

